/// `XmlParseErrorCode`: the detail of a `WRN_XMLParseError` (`XmlSyntaxDiagnosticInfo`).
#[derive(Copy, Clone, PartialEq, Eq, Hash, Debug)]
#[repr(u8)]
pub enum XmlParseErrorCode {
    XML_RefUndefinedEntity_1,
    XML_InvalidCharEntity,
    XML_InvalidUnicodeChar,
    XML_InvalidWhitespace,
    XML_MissingEqualsAttribute,
    XML_StringLiteralNoStartQuote,
    XML_StringLiteralNoEndQuote,
    XML_StringLiteralNonAsciiQuote,
    XML_LessThanInAttributeValue,
    XML_IncorrectComment,
    XML_ElementTypeMatch,
    XML_DuplicateAttribute,
    XML_WhitespaceMissing,
    XML_EndTagNotExpected,
    XML_CDataEndTagNotAllowed,
    XML_EndTagExpected,
    XML_ExpectedIdentifier,
    XML_ExpectedEndOfTag,
    XML_InvalidToken,
    XML_ExpectedEndOfXml,
}

static XML_MESSAGES: [&str; 20] = [
    "Reference to undefined entity '{0}'.",
    "An invalid character was found inside an entity reference.",
    "Invalid unicode character.",
    "Whitespace is not allowed at this location.",
    "Missing equals sign between attribute and attribute value.",
    "A string literal was expected, but no opening quotation mark was found.",
    "Missing closing quotation mark for string literal.",
    "Non-ASCII quotations marks may not be used around string literals.",
    "The character '<' cannot be used in an attribute value.",
    "Incorrect syntax was used in a comment.",
    "End tag '{0}' does not match the start tag '{1}'.",
    "Duplicate '{0}' attribute",
    "Required white space was missing.",
    "End tag was not expected at this location.",
    "The literal string ']]>' is not allowed in element content.",
    "Expected an end tag for element '{0}'.",
    "An identifier was expected.",
    "Expected '>' or '/>' to close tag '{0}'.",
    "The character(s) '{0}' cannot be used at this location.",
    "Unexpected character at this location.",
];

impl XmlParseErrorCode {
    /// The English message format.
    pub fn message_format(self) -> &'static str {
        XML_MESSAGES[self as usize]
    }
}
